const row=(o,full=false)=>`<tr>${full?'<td><input type="checkbox" aria-label="Сонгох"></td>':''}<td class="order-id">${o.id}</td><td><div class="customer-cell"><div class="avatar">${initials(o.customer)}</div><div><strong>${o.customer}</strong><small>${o.phone}</small></div></div></td>${full?`<td>${o.address}</td>`:`<td>${o.product}</td>`}<td><strong>${money(o.amount)}</strong></td><td><span class="status ${slug(o.status)}">${o.status}</span></td><td>${o.date}</td><td><button class="more-btn" aria-label="Дэлгэрэнгүй"><i data-lucide="ellipsis"></i></button></td></tr>`;
