function renderOrders(list=orders){document.querySelector('#recent-orders').innerHTML=list.slice(0,5).map(o=>row(o)).join('');document.querySelector('#orders-table').innerHTML=list.map(o=>row(o,true)).join('');document.querySelector('#all-count').textContent=orders.length;document.querySelector('#order-badge').textContent=orders.length;document.querySelector('#result-count').textContent=`${list.length} үр дүн`;icons()}
function filteredProducts(){const q=document.querySelector('#product-search').value.trim().toLowerCase(),category=document.querySelector('#category-filter').value;return products.filter(p=>(!category||p.category===category)&&(!q||`${p.name} ${p.sku}`.toLowerCase().includes(q)))}
function renderProducts(){const filtered=filteredProducts(),pages=Math.max(1,Math.ceil(filtered.length/productPageSize));productPage=Math.min(productPage,pages);const shown=filtered.slice((productPage-1)*productPageSize,productPage*productPageSize);document.querySelector('#product-grid').innerHTML=shown.map(p=>`<article class="product-card"><button class="product-edit" data-edit-product="${p.id}" aria-label="Бараа засах"><i data-lucide="pencil"></i></button><div class="product-visual"><i data-lucide="package"></i></div><div class="product-body"><h3 title="${p.name}">${p.name}</h3><p>${p.sku||'Кодгүй'}</p><div class="product-meta">${p.category}</div><div class="product-price"><strong>${money(p.price)}</strong><span>${p.stock} үлдэгдэл</span></div></div></article>`).join('')||'<div class="empty-products">Илэрц олдсонгүй.</div>';document.querySelector('#catalog-count').textContent=`${filtered.length.toLocaleString()} бараа`;document.querySelector('#product-page').textContent=`${productPage} / ${pages} хуудас`;document.querySelector('#product-prev').disabled=productPage===1;document.querySelector('#product-next').disabled=productPage===pages;document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>openProductModal(b.dataset.editProduct));const low=[...products].sort((a,b)=>a.stock-b.stock).slice(0,12);document.querySelector('#inventory-list').innerHTML=low.map(p=>`<div class="inventory-item"><span class="inventory-icon"><i data-lucide="package"></i></span><div><strong>${p.name}</strong><small>${p.sku||'Кодгүй'} · ${p.category}</small></div><div class="stock-track ${p.stock<10?'low':''}"><span style="width:${Math.min(100,p.stock)}%"></span></div><b>${p.stock} ш</b></div>`).join('');document.querySelector('#product-count').textContent=products.length.toLocaleString();document.querySelector('#out-count').textContent=products.filter(p=>p.stock<=0).length.toLocaleString();document.querySelector('#stock-value').textContent=money(products.reduce((sum,p)=>sum+p.stock*p.cost,0));icons()}
function renderDelivery(){document.querySelector('#courier-list').innerHTML=couriers.map((c,i)=>`<div class="courier-card"><div class="avatar ${i%2?'teal':''}">${c.initial}</div><div><strong>${c.name}</strong><small>${c.route}</small></div><b>${c.rate}</b></div>`).join('');document.querySelector('#delivery-table').innerHTML=orders.filter(o=>['Замд','Бэлтгэж буй'].includes(o.status)).map((o,i)=>`<tr><td class="order-id">${o.id}</td><td>${o.customer}</td><td>${o.address.split(',')[0]}</td><td>${couriers[i%4].name}</td><td>${11+i}:30</td><td><span class="status ${slug(o.status)}">${o.status}</span></td></tr>`).join('')}
function leadClass(s){return {'Шинэ':'new','Утас аваагүй':'preparing','Дахин холбогдох':'moving','Эргээд залгах':'moving','Захиалга болсон':'delivered'}[s]||'new'}
function renderLeads(){const q=document.querySelector('#lead-search').value.toLowerCase(),page=document.querySelector('#lead-page-filter').value,statusFilter=document.querySelector('#lead-status-filter').value,selectedStatus=leadStatus||statusFilter,archived=['Авахаа больсон','Цуцалсан','Бусад'];const active=leads.filter(l=>!archived.includes(l.status)),source=selectedStatus?leads:active,followUpStatuses=['Утас аваагүй','Дахин холбогдох','Холбогдох боломжгүй','Эргээд залгах'];const list=source.filter(l=>(!selectedStatus||l.status===selectedStatus)&&(!page||l.page===page)&&Object.values(l).join(' ').toLowerCase().includes(q));document.querySelector('#leads-table').innerHTML=list.map((l,i)=>`<tr><td><strong>${i+1}</strong><small class="lead-time"> · ${l.created}</small></td><td><div class="lead-contact"><strong>${l.customer||'Нэргүй'} · ${l.phone}</strong><small>${l.comment}</small></div></td><td><span class="page-chip">${l.page}</span></td><td><strong>${l.product}</strong></td><td><strong>${l.operator}</strong><small class="call-count">${l.attempts||0} удаа залгасан</small></td><td><button class="status-display ${leadClass(l.status)}" data-open-lead-status="${l.id}">${l.status}</button></td><td><div class="lead-actions"><button class="call" data-lead-action="call" data-id="${l.id}" title="Залгалт бүртгэх"><i data-lucide="phone"></i></button><button class="convert" data-lead-action="convert" data-id="${l.id}" title="Захиалга болгох"><i data-lucide="shopping-bag"></i></button></div></td></tr>`).join('')||'<tr><td colspan="7">Илэрц олдсонгүй.</td></tr>';document.querySelector('#lead-total').textContent=leads.length;document.querySelector('#lead-new').textContent=active.filter(l=>l.status==='Шинэ'||followUpStatuses.includes(l.status)).length;document.querySelector('#lead-converted').textContent=leads.filter(l=>l.status==='Захиалга болсон').length;document.querySelector('#lead-failed').textContent=active.filter(l=>followUpStatuses.includes(l.status)).length;document.querySelector('#lead-dropped').textContent=leads.filter(l=>l.status==='Авахаа больсон').length;document.querySelector('#lead-cancelled').textContent=leads.filter(l=>l.status==='Цуцалсан').length;document.querySelector('#lead-badge').textContent=active.filter(l=>l.status==='Шинэ'||followUpStatuses.includes(l.status)).length;document.querySelector('#lead-count').textContent=`${list.length} дугаар`;const operatorStats=Object.values(leads.reduce((result,l)=>{const name=l.operator||'Хуваарилаагүй';result[name]||={name,total:0,attempts:0,converted:0,followUp:0};result[name].total++;result[name].attempts+=Number(l.attempts||0);if(l.status==='Захиалга болсон')result[name].converted++;if(followUpStatuses.includes(l.status))result[name].followUp++;return result},{}));document.querySelector('#operator-grid').innerHTML=operatorStats.map(o=>`<article class="operator-card"><div class="operator-card-head"><span class="avatar small teal">${initials(o.name)}</span><div><strong>${o.name}</strong><small>${o.total} дугаар хуваарилсан</small></div><b>${o.total?Math.round(o.converted/o.total*100):0}%</b></div><div class="operator-card-metrics"><span><small>Залгалт</small><strong>${o.attempts}</strong></span><span><small>Захиалга</small><strong>${o.converted}</strong></span><span><small>Дахин залгах</small><strong>${o.followUp}</strong></span></div></article>`).join('')||'<p class="empty-products">Операторын мэдээлэл алга.</p>';document.querySelectorAll('[data-lead-action]').forEach(b=>b.onclick=()=>updateLead(Number(b.dataset.id),b.dataset.leadAction));document.querySelectorAll('[data-open-lead-status]').forEach(b=>b.onclick=()=>openLeadStatusModal(Number(b.dataset.openLeadStatus)));icons()}
function updateLead(id,action,value){const lead=leads.find(l=>l.id===id);if(!lead)return;if(action==='call'){lead.attempts=(lead.attempts||0)+1;lead.status=lead.attempts>1?'Дахин холбогдох':'Утас аваагүй';lead.lastCall=new Date().toISOString()}if(action==='status')lead.status=value;if(action==='convert'){showView('orders');openModal(id);const form=document.querySelector('#order-form'),p=products.find(x=>x.id===lead.productId);form.elements.customer.value=lead.customer;form.elements.phone.value=lead.phone;form.elements.sourcePage.value=lead.page;form.elements.productId.value=lead.productId;document.querySelector('#order-product-search').value=lead.product;document.querySelector('#selected-order-product').textContent=p?`${p.name} · ${p.sku} · ${money(p.price)}`:lead.product;if(p){form.elements.amount.value=p.price;form.elements.collectAmount.value=p.price}}localStorage.setItem('nexerp-leads',JSON.stringify(leads));renderLeads()}
const leadStatusModal=document.querySelector('#lead-status-modal'),leadStatusForm=document.querySelector('#lead-status-form');function openLeadStatusModal(id){const lead=leads.find(l=>l.id===id);if(!lead)return;leadStatusForm.elements.leadId.value=id;leadStatusForm.elements.status.value=lead.status;document.querySelector('#lead-status-title').textContent=lead.customer||'Нэргүй';document.querySelector('#lead-status-summary').innerHTML=`<strong>${lead.phone}</strong><span>${lead.page}</span><span>${lead.product}</span><small>${lead.attempts||0} удаа залгасан</small>`;leadStatusModal.classList.add('open');leadStatusModal.setAttribute('aria-hidden','false')}function closeLeadStatusModal(){leadStatusModal.classList.remove('open');leadStatusModal.setAttribute('aria-hidden','true')}document.querySelector('#lead-status-close').onclick=closeLeadStatusModal;document.querySelector('#lead-status-cancel').onclick=closeLeadStatusModal;leadStatusModal.onclick=e=>{if(e.target===leadStatusModal)closeLeadStatusModal()};leadStatusForm.onsubmit=e=>{e.preventDefault();updateLead(Number(leadStatusForm.elements.leadId.value),'status',leadStatusForm.elements.status.value);closeLeadStatusModal()};
function renderMenus(){const reports=[['chart-column-big','Борлуулалтын тайлан','Салбар, бараа, сувгаар'],['truck','Хүргэлтийн тайлан','Гүйцэтгэл, хугацаа, ажилтнаар'],['package-search','Агуулахын тайлан','Үлдэгдэл, хөдөлгөөн, тооллого'],['users','Харилцагчийн тайлан','Давтамж, сегмент, өсөлт']];document.querySelector('#report-grid').innerHTML=reports.map(x=>`<button><span><i data-lucide="${x[0]}"></i></span><div><strong>${x[1]}</strong><small>${x[2]}</small></div><i data-lucide="arrow-right"></i></button>`).join('')}
